/// When dumping to the filesystem, data partitions are size-limited to 256KiB.
///
/// There is no single, optimal size for these partitions, because it depends on
/// configuration values that we can't predict or control, such as the version
/// of HTTP used (HTTP/1.1 would work better with larger files, while HTTP/2
/// and 3 are more agnostic), transport compression (gzip, zstd, etc), whether
/// the search query is going to produce a large number of results or a small
/// number, the bandwidth delay product of the network...
///
/// 256KiB is chosen after benching the wordnet data set with the lev+trans
/// automata. Using smaller partitions results in too many roundtrips.
///
/// [1]: https://en.wikipedia.org/wiki/Maximum_transmission_unit#MTUs_for_common_media
/// [2]: https://en.wikipedia.org/wiki/Sliding_window_protocol#Basic_concept
/// [3]: https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/description-tcp-features
const FILE_SIZE_LIMIT: usize = 96 * 1024;

const CHILD_IS_LARGE_LIMIT: usize = 64;

/// Generates the search tree in a JS-wrapped disk format.
///
/// # Parameters
///
/// - `tree`: This is the output of [`crate::internals::tree::encode_search_tree_ukkonen`].
/// - `child_path`: The name of the directory (which will be created) to drop child nodes.
///
/// # Format
///
/// The root of the tree looks like this:
///
/// ```js
/// rr_('{"<COL>"{<COLDATA>,"I":"<NODEDATA>"},...}')
/// ```
///
/// This function returns the NODEDATA, but not the wrapper function or the COLDATA part.
/// The COLDATA is returned by [`write_data_to_disk`].
/// The function wrapper needs to be generated by the caller.
///
/// Child nodes in the search tree have `rn_("<NODEDATA>")`, and go in `index_path/HASH.js`.
///
/// See `HACKING.md` for a description of the format in more detail.
pub fn write_tree_to_disk(
    tree: &SearchTree,
    child_path: impl AsRef<Path>,
    root_write: &mut Vec<u8>,
) -> Result<(), std::io::Error> {
    let child_path = child_path.as_ref();
    std::fs::create_dir_all(child_path)?;
    let mut disk = self::fs::Disk::new(child_path);
    let root = write_tree(tree, &mut disk)?;
    encode::write_base64_to_bytes(&root, root_write)
}

pub fn write_tree(tree: &SearchTree, fs: &mut impl Filesystem) -> Result<Vec<u8>, std::io::Error> {
    write_tree_with_custom_hasher::<sip::Hasher>(tree, fs)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum AlphaBitmap {
    VowelsOnly,
    ConsonantsOnly,
    Hex,
    Short,
    Long,
    Ascii,
    RawByte,
}

impl AlphaBitmap {
    /// The number of characters in the bitmap.
    fn len(self) -> u16 {
        match self {
            AlphaBitmap::VowelsOnly => 5,
            AlphaBitmap::ConsonantsOnly => 21,
            AlphaBitmap::Hex => 16,
            AlphaBitmap::Short => 24,
            AlphaBitmap::Long => 32,
            AlphaBitmap::Ascii => 128,
            AlphaBitmap::RawByte => 256,
        }
    }

    /// Length of the bitmap in bytes, excluding the flag itself.
    fn bytes(self) -> u8 {
        match self {
            Self::VowelsOnly => 0,
            Self::ConsonantsOnly => 2,
            Self::Hex => 2,
            Self::Short => 3,
            Self::Long => 4,
            Self::Ascii => 16,
            Self::RawByte => 32,
        }
    }

    /// Whether the bitmap contains a character `c`.
    fn contains(self, c: u8) -> bool {
        match self {
            Self::VowelsOnly => matches!(c, b'a' | b'e' | b'i' | b'o' | b'u'),
            Self::ConsonantsOnly => {
                matches!(c, b'b'..=b'z') && !matches!(c, b'e' | b'i' | b'o' | b'u')
            }
            Self::Hex => matches!(c, b'0'..=b'9' | b'a'..=b'f'),
            Self::Short => c.is_ascii_lowercase() && !matches!(c, b'q' | b'v'),
            Self::Long => matches!(c, b'1'..=b'6' | b'a'..=b'z'),
            Self::Ascii => c < 128,
            Self::RawByte => true,
        }
    }

    /// The index of a character `c` in the bitmap.
    ///
    /// This function assumes that the bitmap [contains](Self::contains) the character,
    /// otherwise it may panic or return an undefined value.
    fn index(self, c: u8) -> u8 {
        debug_assert!(self.contains(c));
        match self {
            Self::VowelsOnly => b"aeiou".iter().position(|entry| *entry == c).unwrap() as u8,
            Self::ConsonantsOnly => {
                let mut i = c - b'a';
                if c > b'a' {
                    i -= 1;
                }
                if c > b'e' {
                    i -= 1;
                }
                if c > b'i' {
                    i -= 1;
                }
                if c > b'o' {
                    i -= 1;
                }
                if c > b'u' {
                    i -= 1;
                }
                i
            }
            Self::Hex => {
                if let b'0'..=b'9' = c {
                    c - b'0'
                } else {
                    c - b'a' + 10
                }
            }
            Self::Short => {
                let mut i = c - b'a';
                if c > b'q' {
                    i -= 1;
                }
                if c > b'v' {
                    i -= 1;
                }
                i
            }
            Self::Long => {
                if let b'1'..=b'6' = c {
                    c - b'1'
                } else {
                    c - b'a' + 6
                }
            }
            Self::Ascii | Self::RawByte => c,
        }
    }

    fn flag(self) -> u8 {
        match self {
            AlphaBitmap::VowelsOnly => 0x80, // 32, which is, not coincidentally, the RawByte cutoff
            AlphaBitmap::ConsonantsOnly => 0xc0,
            AlphaBitmap::Hex => 0xfc,
            AlphaBitmap::Short => 0xfd,
            AlphaBitmap::Long => 0xfe,
            AlphaBitmap::Ascii => 0xf0,
            AlphaBitmap::RawByte => 0xff,
        }
    }
}

fn write_hash_to_filename(hash: u64, filename: &mut String) {
    filename.reserve(10);
    write_hex_to_string((hash >> 32) as u8, filename);
    write_hex_to_string((hash >> 24) as u8, filename);
    write_hex_to_string((hash >> 16) as u8, filename);
    write_hex_to_string((hash >> 8) as u8, filename);
    write_hex_to_string(hash as u8, filename);
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum NodeBranchRepr {
    InlineNeighbors {
        leaves_count: u32,
    },
    Compressed {
        is_stack_compressed: bool,
        is_long_compressed: bool,
        is_all_compressed: bool,
        compression_bitmap: u32,
    },
    Canonical,
}

impl NodeBranchRepr {
    fn is_inline_neighbors(self) -> bool {
        matches!(self, NodeBranchRepr::InlineNeighbors { .. })
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum NodeDataRepr {
    Data { start: usize, len: u8 },
    DictionaryCompressed { offset: u8 },
}

/// Represents the byte that labels a child node.
/// On the wire, this is a byte, plus, optionally, a bitmap,
/// because that's what we need to figure out how many children we have.
#[derive(Clone, Debug, Eq, PartialEq)]
enum NodeEdgeRepr {
    /// The edges are represented as a list of bytes.
    /// The bytes are stored after the hashes and offsets, if any,
    /// and will need to be gathered then.
    ///
    /// The list representation is never used for a number of bytes >= 32.
    /// That always uses `Bitmap(AlphaBitmap::RawByte)`, because the bitmap
    /// for raw bytes is, itself, 32 bytes long.
    List(usize),
    // The edges are represented as a bitmap.
    // This representation doesn't explicitly store the size; instead, you
    // need to count the ones in the bitmap. This gives us plently of bits
    // to identify which alphabet we're using.
    Bitmap(AlphaBitmap, [u8; 32]),
}

impl NodeEdgeRepr {
    fn new(edges: impl Iterator<Item = u8> + ExactSizeIterator + Clone) -> NodeEdgeRepr {
        fn is_valid_alphabitmap(
            alphabitmap: AlphaBitmap,
            mut edges: impl Iterator<Item = u8> + ExactSizeIterator,
        ) -> bool {
            edges.len() <= alphabitmap.len().into()
                && edges.len() > alphabitmap.bytes().into()
                && edges.all(|byte| alphabitmap.contains(byte))
        }
        fn make_bitmap(
            alphabitmap: AlphaBitmap,
            edges: impl Iterator<Item = u8> + ExactSizeIterator,
        ) -> NodeEdgeRepr {
            let mut bm = [0; 32];
            for edge in edges {
                let i = alphabitmap.index(edge);
                bm[usize::from(i >> 3)] |= 1 << (i & 0x07);
            }
            NodeEdgeRepr::Bitmap(alphabitmap, bm)
        }
        if is_valid_alphabitmap(AlphaBitmap::VowelsOnly, edges.clone()) {
            return make_bitmap(AlphaBitmap::VowelsOnly, edges.clone());
        }
        if is_valid_alphabitmap(AlphaBitmap::ConsonantsOnly, edges.clone()) {
            return make_bitmap(AlphaBitmap::ConsonantsOnly, edges.clone());
        }
        if is_valid_alphabitmap(AlphaBitmap::Hex, edges.clone()) {
            return make_bitmap(AlphaBitmap::Hex, edges.clone());
        }
        if is_valid_alphabitmap(AlphaBitmap::Short, edges.clone()) {
            return make_bitmap(AlphaBitmap::Short, edges.clone());
        }
        if is_valid_alphabitmap(AlphaBitmap::Long, edges.clone()) {
            return make_bitmap(AlphaBitmap::Long, edges.clone());
        }
        if is_valid_alphabitmap(AlphaBitmap::Ascii, edges.clone()) {
            return make_bitmap(AlphaBitmap::Ascii, edges.clone());
        }
        if edges.len() >= 32 {
            return make_bitmap(AlphaBitmap::RawByte, edges.clone());
        }
        NodeEdgeRepr::List(edges.len())
    }
    fn parse(flag: u8, input: &[u8]) -> (NodeEdgeRepr, usize) {
        let mut i = 0;
        let mut bm = [0; 32];
        let edges = if flag == AlphaBitmap::Hex.flag() {
            NodeEdgeRepr::Bitmap(AlphaBitmap::Hex, {
                bm[0..2].copy_from_slice(&input[0..2]);
                i += 2;
                bm
            })
        } else if flag == AlphaBitmap::Short.flag() {
            NodeEdgeRepr::Bitmap(AlphaBitmap::Short, {
                bm[0..3].copy_from_slice(&input[0..3]);
                i += 3;
                bm
            })
        } else if flag == AlphaBitmap::Long.flag() {
            NodeEdgeRepr::Bitmap(AlphaBitmap::Long, {
                bm[0..4].copy_from_slice(&input[0..4]);
                i += 4;
                bm
            })
        } else if flag == AlphaBitmap::Ascii.flag() {
            NodeEdgeRepr::Bitmap(AlphaBitmap::Ascii, {
                bm[0..16].copy_from_slice(&input[0..16]);
                i += 16;
                bm
            })
        } else if flag == AlphaBitmap::RawByte.flag() {
            NodeEdgeRepr::Bitmap(AlphaBitmap::RawByte, {
                bm[0..32].copy_from_slice(&input[0..32]);
                i += 32;
                bm
            })
        } else if flag >= AlphaBitmap::ConsonantsOnly.flag() {
            NodeEdgeRepr::Bitmap(AlphaBitmap::ConsonantsOnly, {
                bm[2] = flag & 0x1f;
                bm[0..2].copy_from_slice(&input[0..2]);
                i += 2;
                bm
            })
        } else if flag >= AlphaBitmap::VowelsOnly.flag() {
            NodeEdgeRepr::Bitmap(AlphaBitmap::VowelsOnly, {
                bm[0] = flag & 0x1f;
                bm
            })
        } else {
            NodeEdgeRepr::List(flag.into())
        };
        (edges, i)
    }
    fn len(&self) -> usize {
        match self {
            NodeEdgeRepr::List(len) => *len,
            NodeEdgeRepr::Bitmap(_, bitmap) => {
                bitmap.iter().map(|byte| byte.count_ones() as usize).sum()
            }
        }
    }
    fn write(&self, outbuf: &mut Vec<u8>) {
        self.write_flag(outbuf);
        self.write_alphabitmap(outbuf);
    }
    fn write_flag(&self, outbuf: &mut Vec<u8>) {
        match self {
            NodeEdgeRepr::List(len) => outbuf.push(u8::try_from(*len).unwrap()),
            NodeEdgeRepr::Bitmap(AlphaBitmap::VowelsOnly, bitmap) => {
                outbuf.push(AlphaBitmap::VowelsOnly.flag() | bitmap[0]);
            }
            NodeEdgeRepr::Bitmap(AlphaBitmap::ConsonantsOnly, bitmap) => {
                outbuf.push(AlphaBitmap::ConsonantsOnly.flag() | bitmap[2]);
            }
            NodeEdgeRepr::Bitmap(alphabitmap, _bitmap) => {
                outbuf.push(alphabitmap.flag());
            }
        }
    }
    fn write_alphabitmap(&self, outbuf: &mut Vec<u8>) {
        match self {
            NodeEdgeRepr::List(_len) => {}
            NodeEdgeRepr::Bitmap(AlphaBitmap::VowelsOnly, _bitmap) => {}
            NodeEdgeRepr::Bitmap(AlphaBitmap::ConsonantsOnly, bitmap) => {
                outbuf.extend_from_slice(&bitmap[0..2]);
            }
            NodeEdgeRepr::Bitmap(alphabitmap, bitmap) => {
                outbuf.extend(bitmap.iter().take(alphabitmap.bytes().into()).copied());
            }
        }
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct NodeHeader {
    is_pure_suffixes_only_node: bool,
    node_branch_repr: NodeBranchRepr,
    node_data_repr: NodeDataRepr,
    is_no_leaves: bool,
    is_no_branches: bool,
    mhp_edges: NodeEdgeRepr,
    so_edges: NodeEdgeRepr,
}
impl NodeHeader {
    fn parse(outbuf: &[u8]) -> (NodeHeader, usize) {
        let mut i = 0;
        let mut compression_tag = outbuf[i] as u32;
        let is_pure_suffixes_only_node = (compression_tag & 0x01) != 0;
        let is_stack_compressed = (compression_tag & 0x02) != 0;
        let is_long_compressed = (compression_tag & 0x04) != 0;
        let is_dictionary_compressed = (compression_tag & 0x08) != 0 && !is_pure_suffixes_only_node;
        let is_all_compressed = (compression_tag & 0xF0) == 0xF0 && !is_long_compressed;
        let is_compressed = (compression_tag & 0xF0) != 0x00 || is_long_compressed;
        i += 1;
        if is_long_compressed {
            compression_tag |= u32::from(outbuf[i]) << 8;
            i += 1;
        }
        let (node_data_repr, is_no_branches, is_no_leaves) =
            if is_pure_suffixes_only_node && (compression_tag & 0x08) != 0 {
                (NodeDataRepr::Data { start: i, len: 0 }, false, true)
            } else {
                let data_len = outbuf[i] & 0x3F;
                let is_no_branches = outbuf[i] & 0x40 != 0;
                let is_no_leaves = outbuf[i] & 0x80 != 0;
                i += 1;
                let data_start = i;
                if is_dictionary_compressed {
                    (
                        NodeDataRepr::DictionaryCompressed { offset: data_len },
                        is_no_branches,
                        is_no_leaves,
                    )
                } else {
                    if !is_pure_suffixes_only_node {
                        i += data_len as usize;
                    }
                    (
                        NodeDataRepr::Data {
                            start: data_start,
                            len: data_len,
                        },
                        is_no_branches,
                        is_no_leaves,
                    )
                }
            };
        let is_inline_neighbors = is_no_leaves && is_no_branches;
        if is_inline_neighbors {
            let branches_flag = if is_long_compressed {
                u8::try_from(compression_tag >> 8).unwrap()
            } else {
                0
            };
            let leaves_count = (compression_tag >> 4) & 0x0f;
            let (branches_edges, consumed_len) = NodeEdgeRepr::parse(branches_flag, &outbuf[i..]);
            i += consumed_len;
            let (mhp_edges, so_edges) = if is_pure_suffixes_only_node {
                (NodeEdgeRepr::List(0), branches_edges)
            } else {
                (branches_edges, NodeEdgeRepr::List(0))
            };
            return (
                NodeHeader {
                    is_pure_suffixes_only_node,
                    node_branch_repr: NodeBranchRepr::InlineNeighbors { leaves_count },
                    node_data_repr,
                    is_no_leaves,
                    is_no_branches,
                    mhp_edges,
                    so_edges,
                },
                i,
            );
        }
        let mhp_edges = if is_pure_suffixes_only_node || is_no_branches {
            NodeEdgeRepr::List(0)
        } else {
            let flag = outbuf[i];
            i += 1;
            let (mhp_edges, consumed_len) = NodeEdgeRepr::parse(flag, &outbuf[i..]);
            i += consumed_len;
            mhp_edges
        };
        let so_edges = if is_no_branches {
            NodeEdgeRepr::List(0)
        } else {
            let flag = outbuf[i];
            i += 1;
            let (so_edges, consumed_len) = NodeEdgeRepr::parse(flag, &outbuf[i..]);
            i += consumed_len;
            so_edges
        };
        (
            NodeHeader {
                is_pure_suffixes_only_node,
                node_branch_repr: if is_compressed {
                    NodeBranchRepr::Compressed {
                        is_stack_compressed,
                        is_long_compressed,
                        is_all_compressed,
                        compression_bitmap: compression_tag >> 4,
                    }
                } else {
                    NodeBranchRepr::Canonical
                },
                is_no_leaves,
                is_no_branches,
                node_data_repr,
                mhp_edges,
                so_edges,
            },
            i,
        )
    }
    fn count_compressed_children(&self) -> usize {
        match self.node_branch_repr {
            NodeBranchRepr::Canonical | NodeBranchRepr::InlineNeighbors { .. } => 0,
            NodeBranchRepr::Compressed {
                is_all_compressed,
                compression_bitmap,
                ..
            } => {
                if is_all_compressed {
                    self.mhp_edges.len() + self.so_edges.len()
                } else {
                    compression_bitmap.count_ones() as usize
                }
            }
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum DefinitelyStackCompressible {
    Yes,
    No,
}

pub fn write_tree_with_custom_hasher<H: Hasher>(
    tree: &SearchTree,
    fs: &mut impl Filesystem,
) -> Result<Vec<u8>, std::io::Error> {
    /// Convert a subtree chunk to a file.
    /// This function also does dictionary compression.
    fn subtree_to_bytes(
        outbuf: &mut Vec<u8>,
        subtree: impl Iterator<Item = ((u32, u8), (Range<usize>, Range<usize>))>,
    ) -> &[u8] {
        let mut dict = VecDeque::new();
        let start = outbuf.len();
        for (_, (_, compressed)) in subtree {
            let node_start = compressed.start;
            let is_pure_suffix_tree = outbuf[node_start] & 0x01 != 0;
            if !is_pure_suffix_tree
                && let is_long_compressed = outbuf[node_start] & 0x04 != 0
                && let doff = if is_long_compressed { 2 } else { 1 }
                && let dlen = usize::from(outbuf[node_start + doff]) & 0x3F
                && dlen != 0
            {
                let no_leaves_flag = outbuf[node_start + doff] & 0x80;
                let no_branches_flag = outbuf[node_start + doff] & 0x40;
                let data = node_start + doff + 1..node_start + dlen + doff + 1;
                if let Some(backref) = dict
                    .iter()
                    .cloned()
                    .position(|dentry| outbuf[dentry] == outbuf[data.clone()])
                {
                    outbuf.push(outbuf[node_start] | 0x08); // flag node as dictionary compressed
                    if is_long_compressed {
                        outbuf.push(outbuf[node_start + 1]);
                    }
                    outbuf.push(u8::try_from(backref).unwrap() | no_leaves_flag | no_branches_flag);
                    outbuf.extend_from_within(compressed.start + dlen + doff + 1..compressed.end);
                } else {
                    outbuf.extend_from_within(compressed);
                }
                dict.push_front(data);
                if dict.len() > 0x3F {
                    dict.pop_back();
                }
            } else {
                outbuf.extend_from_within(compressed);
            }
        }
        &outbuf[start..]
    }

    #[rustfmt::skip]
    fn inline_neighbors_special_node_repr<H: Hasher>(
        disambig_level: usize,
        node: &SearchTreeBranchNode,
        tree: &SearchTree,
        bundled_subtree_hashes_lower: &mut Vec<u32>,
        bundled_subtree_hashes_upper: &mut Vec<u8>,
        bundled_subtree_offsets: &mut Vec<(Range<usize>, Range<usize>)>,
        outbuf: &mut Vec<u8>,
    ) -> io::Result<ControlFlow<()>> {
        if // special representation for nodes that...
            // haven't hit a hash collision (because this format has no redundant space for it)
            disambig_level == 0 &&
            // ...have at most 7 leaves (that's all that fits in the field)
            node.leaves.len() < 0x08 &&
            // ...do not require data to be chopped up (the format could support it, but the code doesn't)
            node.data.len() <= 0x3F &&
            // ...have only one kind of direct leaf
            (node.suffixes_only || (
                node.leaves.leaves_suffix.is_empty() &&
                node.branch_values().all(|child_node| !tree.nodes[child_node].suffixes_only)
            )) &&
            // ...has only direct branches, no sub-branches, and all fulfill the leaf repr reqs
            node.branch_values().all(|child_node| {
                let node = &tree.nodes[child_node];
                node.branches.is_empty() &&
                    node.leaves.len() < 0x08 &&
                    node.data.len() <= 0xF &&
                    (node.suffixes_only || node.leaves.leaves_suffix.is_empty())
            }) &&
            // ...and, most importantly, all transitives leaves have the same 16bit prefix
            let Some(leaf_value_upper) = node.leaves.iter().next()
                .or_else(|| node.branch_values().find_map(|child_node| tree.nodes[child_node].leaves.iter().next()))
                .map(|upper| upper >> 16) &&
            node.leaves.iter().all(|leaf| (leaf >> 16) == leaf_value_upper) &&
            node.branch_values().all(|child_node| tree.nodes[child_node].leaves.iter().all(|leaf| (leaf >> 16) == leaf_value_upper))
        {
            let node = &node;
            let data = &tree.data[node.data.clone()];
            let new_data_start = outbuf.len();
            let leaves = if node.suffixes_only {
                assert!(node.leaves.leaves_whole.is_empty());
                &node.leaves.leaves_suffix[..]
            } else {
                assert!(node.leaves.leaves_suffix.is_empty());
                &node.leaves.leaves_whole[..]
            };
            let is_run = leaves.len() > 1 &&
                leaves.windows(2).all(|window| window[1] - window[0] == 1);
            let inline_neighbors_flag = 0xc0;
            outbuf.push(
                if node.suffixes_only { 0x01 } else { 0 }
                    | if node.branches.is_empty() {
                        0
                    } else {
                        0x04
                    }
                    | (u8::try_from(node.leaves.len()).unwrap() << 4)
                    | if is_run {
                        0x80
                    } else {
                        0x00
                    },
            );
            let branch_edge_repr = NodeEdgeRepr::new(node.branch_keys());
            if branch_edge_repr.len() != 0 {
                branch_edge_repr.write_flag(outbuf);
            }
            outbuf.push(
                u8::try_from(data.len()).expect("data len must be less than 64")
                    | inline_neighbors_flag,
            );
            if !node.suffixes_only {
                outbuf.extend(data);
            }
            branch_edge_repr.write_alphabitmap(outbuf);
            outbuf.extend(lower_u16_to_le_bytes(leaf_value_upper));
            for child_node in node.branch_values() {
                let child_node = &tree.nodes[child_node];
                let child_leaves = if node.suffixes_only {
                    assert!(child_node.leaves.leaves_whole.is_empty());
                    &child_node.leaves.leaves_suffix[..]
                } else {
                    assert!(child_node.leaves.leaves_suffix.is_empty());
                    &child_node.leaves.leaves_whole[..]
                };
                let child_is_run = child_leaves.len() > 1 &&
                    child_leaves.windows(2).all(|win| win[1] - win[0] == 1);
                outbuf.push(
                    u8::try_from(
                        child_node.data.len()
                            | (child_leaves.len() << 4)
                            | if child_is_run { 0x80 } else { 0x00 },
                    )
                    .unwrap(),
                );
                if !node.suffixes_only {
                    outbuf.extend_from_slice(&tree.data[child_node.data.clone()]);
                }
                if child_is_run {
                    outbuf.extend(lower_u16_to_le_bytes(child_leaves[0]));
                } else {
                    outbuf.extend(child_leaves.iter().copied().flat_map(lower_u16_to_le_bytes));
                }
            }
            if let NodeEdgeRepr::List(_) = branch_edge_repr {
                outbuf.extend(node.branch_keys());
            }
            if is_run {
                outbuf.extend(lower_u16_to_le_bytes(leaves[0]));
            } else {
                outbuf.extend(leaves.iter().copied().flat_map(lower_u16_to_le_bytes));
            }
            let nodeid = H::hash(&outbuf[new_data_start..outbuf.len()]) & 0x0000_007F_FFFF_FFFF;
            bundled_subtree_hashes_lower.push(nodeid as u32);
            bundled_subtree_hashes_upper.push((nodeid >> 32) as u8);
            bundled_subtree_offsets
                .push((new_data_start..outbuf.len(), new_data_start..outbuf.len()));
            Ok(ControlFlow::Break(()))
        } else {
            Ok(ControlFlow::Continue(()))
        }
    }

    #[rustfmt::skip]
    /// Returns a node's file, and writes any child nodes that couldn't be bundled through the `file_writer`.
    ///
    /// This function recursively builds all the children. If all the children have already been built, use `generate_node`.
    fn generate_node_with_bundled_children<H: Hasher>(
        tree: &SearchTree,
        node: usize,
        disambig_level: usize,
        parent_is_suffixes_only: bool,
        fs: &mut impl Filesystem,
        file_existence_cache: &mut HashSet<u64>,
        bundled_subtree_hashes_lower: &mut Vec<u32>,
        bundled_subtree_hashes_upper: &mut Vec<u8>,
        bundled_subtree_offsets: &mut Vec<(Range<usize>, Range<usize>)>,
        outbuf: &mut Vec<u8>,
    ) -> Result<DefinitelyStackCompressible, std::io::Error> {
        let mhp_len = tree.nodes[node]
            .branch_values()
            .filter(|child_node| !tree.nodes[*child_node].suffixes_only)
            .count();
        let so_len = tree.nodes[node]
            .branch_values()
            .filter(|child_node| tree.nodes[*child_node].suffixes_only)
            .count();
        let local_subtree_start = bundled_subtree_hashes_lower.len();
        assert_eq!(local_subtree_start, bundled_subtree_offsets.len());
        assert_eq!(local_subtree_start, bundled_subtree_hashes_upper.len());
        if inline_neighbors_special_node_repr::<H>(
            disambig_level,
            &tree.nodes[node],
            tree,
            bundled_subtree_hashes_lower,
            bundled_subtree_hashes_upper,
            bundled_subtree_offsets,
            outbuf,
        )?
        .is_break()
        {
            return Ok(DefinitelyStackCompressible::Yes);
        }
        // The set of characters, one for each child, that might follow this node
        let mut might_have_prefix_child_keys: Vec<u8> = Vec::with_capacity(mhp_len);
        let mut suffix_only_child_keys: Vec<u8> = Vec::with_capacity(so_len);
        // The hash or inlined data of each child node
        let mut might_have_prefix_child_nodeids: Vec<u64> = Vec::with_capacity(mhp_len);
        let mut suffix_only_child_nodeids: Vec<u64> = Vec::with_capacity(so_len);
        // The filename to write a child to (this buffer is reused for efficiency).
        let mut filename = String::new();
        // The "stack compression" mode works whenever all of the children of this node are bundled in
        // reverse order of its use. This is why they're generated backwards. If none of them are
        // placed in a separate file, and none of them are deduplicated, then we can infer that
        // stack compression will definitely work.
        let mut definitely_stack_compressible = DefinitelyStackCompressible::Yes;
        for (i, child_node) in tree.nodes[node]
            .branch_values()
            .enumerate()
            .filter(|(_, child_node)| tree.nodes[*child_node].suffixes_only)
            .rev()
            .chain(
                tree.nodes[node]
                    .branch_values()
                    .enumerate()
                    .filter(|(_, child_node)| !tree.nodes[*child_node].suffixes_only)
                    .rev(),
            )
        {
            let child_node_suffixes_only = tree.nodes[child_node].suffixes_only;
            let current_node_suffixes_only = tree.nodes[node].suffixes_only;
            let (child_keys, child_nodeids) =
                if !child_node_suffixes_only || mhp_len >= 256 || so_len >= 256 {
                    // if there are 256 child nodes, we overflow the one-byte length marker
                    // to work around this, both bytes are set to 0xff, and we can't distinguish suffix-only
                    // data from prefix-containing data
                    (
                        &mut might_have_prefix_child_keys,
                        &mut might_have_prefix_child_nodeids,
                    )
                } else {
                    (&mut suffix_only_child_keys, &mut suffix_only_child_nodeids)
                };
            child_keys.push(tree.nodes[node].get_branch_key_by_list_index(i));
            let mut disambig_level_child = 0;
            let child_nodeid = 'nodeid: loop {
                let child_data = &tree.data[tree.nodes[child_node].data.clone()];
                let child_leaves = &tree.nodes[child_node].leaves;
                if tree.nodes[child_node].branches.is_empty() {
                    // Inlining:
                    // The first bit of a 40 bit node ID is a tag. If this tag is zero, then
                    // it is a 39bit hash. If it's a 1, then its leaf ID is packed into the
                    // lower 32 bits, and the remaining data contains either a run length
                    // or the number of intermediate data bits in a suffix node.
                    let tagged = if
                        let &[first_id, ..] = &child_leaves.leaves_suffix[..] &&
                        child_leaves.leaves_suffix.len() <= 0x20 &&
                        child_leaves.leaves_suffix.windows(2).all(|pair| pair[1] == pair[0] + 1 && pair[1] >> 16 == pair[0] >> 16) &&
                        child_leaves.leaves_whole.is_empty() &&
                        child_data.is_empty()
                    {
                        // a run of up to 32 IDs of suffix-only matches
                        0x00e0_0000_0000u64 | // 111_ (inlined, suffix-only, run)
                        (u64::try_from(child_leaves.leaves_suffix.len() - 1).expect("len <= 0x20") << 32) |
                        u64::from(first_id)
                    } else if
                        let &[first_id, ..] = &child_leaves.leaves_whole[..] &&
                        child_leaves.leaves_whole.len() <= 0x20 &&
                        child_leaves.leaves_whole.windows(2).all(|pair| pair[1] == pair[0] + 1 && pair[1] >> 16 == pair[0] >> 16) &&
                        child_leaves.leaves_suffix.is_empty() &&
                        child_data.is_empty()
                    {
                        // a run of up to 32 IDs of whole-string prefix matches
                        0x00a0_0000_0000u64 | // 101_ (inlined, run)
                        (u64::try_from(child_leaves.leaves_whole.len() - 1).expect("len <= 0x20") << 32) |
                        u64::from(first_id)
                    } else if
                        // exactly one whole-string prefix match, with one byte of payload data
                        let &[first_id] = &child_leaves.leaves_whole[..] &&
                        child_leaves.leaves_suffix.is_empty() &&
                        let &[ch] = &child_data[..] &&
                        AlphaBitmap::Long.contains(ch)
                    {
                        0x0080_0000_0000u64 | // 100_ (inlined)
                        (u64::from(AlphaBitmap::Long.index(ch)) << 32) |
                        u64::from(first_id)
                    } else if
                        // exactly one suffix-only match, with up to 255 bytes of payload data
                        let &[first_id] = &child_leaves.leaves_suffix[..] &&
                        child_leaves.leaves_whole.is_empty() &&
                        child_data.len() <= 0x20
                    {
                        0x00c0_0000_0000u64 | // 110_ (inlined, suffix-only)
                        (u64::try_from(child_data.len() - 1).expect("len <= 0x20") << 32) |
                        u64::from(first_id)
                    } else {
                        // works as a sentinel because of the tag bits
                        0
                    };
                    if tagged != 0 {
                        if mhp_len + so_len > 12 {
                            // Inlined children are not necessarily a problem for directly
                            // generating a stack compressed node, unless there's too many
                            // children for the compression header to track which children are
                            // compressed and which ones aren't.
                            definitely_stack_compressible = DefinitelyStackCompressible::No;
                        }
                        break 'nodeid tagged;
                    }
                }
                let new_subtree_start = bundled_subtree_hashes_lower.len();
                let new_outbuf_start = outbuf.len();
                stacker::maybe_grow(32 * 1024, 1024 * 1024, || {
                    let was_regular_stack = generate_node_with_bundled_children::<H>(
                        tree,
                        child_node,
                        disambig_level_child,
                        current_node_suffixes_only,
                        fs,
                        file_existence_cache,
                        bundled_subtree_hashes_lower,
                        bundled_subtree_hashes_upper,
                        bundled_subtree_offsets,
                        outbuf,
                    )?;
                    if was_regular_stack == DefinitelyStackCompressible::No {
                        // The basic theory behind directly generating a stack-compressed node
                        // is that we can predict that our children are at the top of the stack.
                        // This only works, though, if we know that our direct child doesn't leave
                        // anything else on the stack, which can happen if it refers to its
                        // children by hash instead of by reference.
                        definitely_stack_compressible = DefinitelyStackCompressible::No;
                    }
                    Ok::<(), std::io::Error>(())
                })?;
                let root_child_nodeid_lower = *bundled_subtree_hashes_lower.last().unwrap();
                let root_child_nodeid_upper = *bundled_subtree_hashes_upper.last().unwrap();
                let root_child_nodeid = (u64::from(root_child_nodeid_upper) << 32) | u64::from(root_child_nodeid_lower);
                let child_is_large = bundled_subtree_offsets[new_subtree_start..]
                    .iter()
                    .map(|(_, compressed)| compressed.len())
                    .sum::<usize>()
                    > CHILD_IS_LARGE_LIMIT;
                if
                // The unbundling heuristics (these are the cases where a node is never bundled):
                (
                        // 1. I don't bundle large nodes that has sixteen ones in a row.
                        //    Remaining zeroes work out to a 1/2**16 pseudo-random chance of unbundling,
                        //    in a context where every node will always make the same choice,
                        //    which improves reuse over doing it based on a size cutoff alone.
                        (root_child_nodeid_lower >= 0xFFFF_0000 && child_is_large)
                        // 2. Suffix-only subtrees are always unbundled from prefix-bearing nodes.
                        //    This reduces the amount of data that levenshtein matching, which ignores suffix-only subtrees,
                        //    winds up pulling down.
                        || (child_node_suffixes_only != current_node_suffixes_only && child_is_large)
                        // 3. I don't bundle data when there's a hash collision (implementation complexity).
                        || disambig_level_child > 0
                        // 4. I limit bundling to 256KiB, as mentioned above.
                        || bundled_subtree_offsets[local_subtree_start..]
                            .iter()
                            .map(|(_, compressed)| compressed.len())
                            .sum::<usize>()
                            > FILE_SIZE_LIMIT
                        // 5. I don't bundle if a file with the same hash already exists.
                        || file_existence_cache.contains(&root_child_nodeid)
                    )
                    // 6. I always bundle a node that has already *been* bundled.
                    // The unbundling heuristics:
                    && !bundled_subtree_hashes_lower[local_subtree_start..new_subtree_start]
                        .iter()
                        .enumerate()
                        .any(|(i, h)| {
                            *h == root_child_nodeid_lower &&
                                bundled_subtree_hashes_upper[i + local_subtree_start] == root_child_nodeid_upper
                        })
                {
                    // We had to flush this node to a separate file.
                    // This means we can't generate a stack compressed node, because
                    // at least one of its children isn't bundled.
                    definitely_stack_compressible = DefinitelyStackCompressible::No;
                    filename.clear();
                    write_hash_to_filename(root_child_nodeid, &mut filename);
                    let flattened_child_data = subtree_to_bytes(
                        outbuf,
                        bundled_subtree_hashes_lower
                            .drain(new_subtree_start..)
                            .zip(bundled_subtree_hashes_upper.drain(new_subtree_start..))
                            .zip(bundled_subtree_offsets.drain(new_subtree_start..)),
                    );
                    if file_existence_cache.contains(&root_child_nodeid)
                        && let Some(other_content) = fs.read_file(&filename)?
                    {
                        if other_content == flattened_child_data {
                            outbuf.truncate(new_outbuf_start);
                            break 'nodeid root_child_nodeid;
                        }
                        disambig_level_child += 1;
                        outbuf.truncate(new_outbuf_start);
                        continue 'nodeid;
                    } else {
                        fs.write_file(&filename, flattened_child_data)?;
                        file_existence_cache.insert(root_child_nodeid);
                        outbuf.truncate(new_outbuf_start);
                        break 'nodeid root_child_nodeid;
                    }
                } else {
                    let mut needs_deleted = TinySet::<usize>::default();
                    let children_hashes_lower = &bundled_subtree_hashes_lower[new_subtree_start..];
                    let children_hashes_upper = &bundled_subtree_hashes_upper[new_subtree_start..];
                    let children_offsets = &bundled_subtree_offsets[new_subtree_start..];
                    // Check if any other nodes inside this file have the same ID.
                    // We don't need to check for conflicts between files (because the loader doesn't use a big global cache) and we already checked for conflicts
                    // between a file and an internal node.
                    {
                        let mut children_hashes_lower_iter =
                            children_hashes_lower.iter().cloned().enumerate().rev();
                        while let Some((mut child_node_idx, mut child_nodeid_lower)) =
                            children_hashes_lower_iter.next()
                        {
                            let mut child_nodeid_upper = children_hashes_upper[child_node_idx];
                            // Yes, I've tried a hashtable. It's slower.
                            // It's probably the per-file size limit preventing this set from ever being truly big.
                            if let Some(mut i) = bundled_subtree_hashes_lower
                                [local_subtree_start..new_subtree_start]
                                .iter()
                                .enumerate()
                                .position(|(i, h)| *h == child_nodeid_lower && bundled_subtree_hashes_upper[i + local_subtree_start] == child_nodeid_upper)
                            {
                                i += local_subtree_start;
                                // if we found a duplicate node, then that means the node we're
                                // generating might not be able to use stack compression
                                definitely_stack_compressible = DefinitelyStackCompressible::No;
                                // if a duplicate node is found, and the found node has stack compression,
                                // then the structure of every node above it must also be identical,
                                // so we can just scan backwards instead of having to do the full check
                                let mut stack_depth = 1;
                                while stack_depth > 0 && child_nodeid_lower == bundled_subtree_hashes_lower[i] && child_nodeid_upper == bundled_subtree_hashes_upper[i] {
                                    let (child_canonical, child_compressed) =
                                        children_offsets[child_node_idx].clone();
                                    let canonical = &bundled_subtree_offsets[i].0;
                                    let compressed = &bundled_subtree_offsets[i].1;
                                    if outbuf[canonical.clone()] != outbuf[child_canonical.clone()]
                                    {
                                        disambig_level_child += 1;
                                        bundled_subtree_hashes_lower.truncate(new_subtree_start);
                                        bundled_subtree_hashes_upper.truncate(new_subtree_start);
                                        bundled_subtree_offsets.truncate(new_subtree_start);
                                        outbuf.truncate(new_outbuf_start);
                                        continue 'nodeid;
                                    }
                                    needs_deleted.push(child_node_idx);
                                    stack_depth -= 1;
                                    let (child_compressed_node, _) =
                                        NodeHeader::parse(&outbuf[child_compressed.start..]);
                                    let (compressed_node, _) =
                                        NodeHeader::parse(&outbuf[compressed.start..]);
                                    match (child_compressed_node.node_branch_repr, compressed_node.node_branch_repr) {
                                        (
                                            NodeBranchRepr::Compressed { is_stack_compressed, compression_bitmap, .. },
                                            NodeBranchRepr::Compressed { is_stack_compressed: child_is_stack_compressed, compression_bitmap: child_compression_bitmap, .. },
                                        ) => {
                                            if !is_stack_compressed || !child_is_stack_compressed || compression_bitmap != child_compression_bitmap {
                                                // if these nodes have different structure,
                                                // or if one of them uses backref compression,
                                                // then we need to handle potentially different orderings
                                                break;
                                            }
                                        }
                                        (NodeBranchRepr::Compressed { .. }, _) => break,
                                        (_, NodeBranchRepr::Compressed { .. }) => break,
                                        _ => {}
                                    }
                                    stack_depth +=
                                        child_compressed_node.count_compressed_children();
                                    if stack_depth != 0 {
                                        (child_node_idx, child_nodeid_lower) =
                                            children_hashes_lower_iter.next().unwrap();
                                        i -= 1;
                                        child_nodeid_upper = children_hashes_upper[child_node_idx];
                                    }
                                }
                            }
                        }
                        for &idx in needs_deleted.iter().rev() {
                            bundled_subtree_hashes_lower.remove(new_subtree_start + idx);
                            bundled_subtree_hashes_upper.remove(new_subtree_start + idx);
                            bundled_subtree_offsets.remove(new_subtree_start + idx);
                        }
                        if let Some(idx) = needs_deleted.first().copied() {
                            let len = bundled_subtree_hashes_lower.len();
                            for child_node_idx in new_subtree_start + idx..len {
                                compress_node_branches(
                                    &mut bundled_subtree_hashes_lower
                                        [local_subtree_start..child_node_idx + 1],
                                    &mut bundled_subtree_hashes_upper
                                        [local_subtree_start..child_node_idx + 1],
                                    &mut bundled_subtree_offsets
                                        [local_subtree_start..child_node_idx + 1],
                                    outbuf,
                                );
                            }
                        }
                    }
                    break 'nodeid root_child_nodeid;
                }
            };
            child_nodeids.push(child_nodeid);
        }
        // To support stack compression, we want the branch list to be in reverse
        // order of the serialized nodes.
        might_have_prefix_child_keys.reverse();
        suffix_only_child_keys.reverse();
        might_have_prefix_child_nodeids.reverse();
        suffix_only_child_nodeids.reverse();
        // If there was a hash conflict, add dummy children to break it up
        if disambig_level != 0 {
            // dummy children don't necessarily follow correct stack discipline,
            // so don't do that
            definitely_stack_compressible = DefinitelyStackCompressible::No;
            let (dummy_node_id, dummy_node_offset) = generate_node::<H>(&[], &[], &[], &[], &[], &[], &[], outbuf);
            bundled_subtree_hashes_lower.push(dummy_node_id as u32);
            bundled_subtree_hashes_upper.push((dummy_node_id >> 32) as u8);
            bundled_subtree_offsets.push((dummy_node_offset.clone(), dummy_node_offset));
            let mut c = 0;
            for _ in 0..disambig_level {
                while might_have_prefix_child_keys.contains(&c)
                    || suffix_only_child_keys.contains(&c)
                {
                    c = c.checked_add(1).unwrap();
                }
                let mut ci = suffix_only_child_keys.len();
                suffix_only_child_keys.push(c);
                suffix_only_child_nodeids.push(dummy_node_id);
                while ci > 0 && suffix_only_child_keys[ci - 1] > c {
                    suffix_only_child_keys.swap(ci, ci - 1);
                    suffix_only_child_nodeids.swap(ci, ci - 1);
                    ci -= 1;
                }
            }
        }
        // Now that every child has been computed, do this node
        let mut data = tree.nodes[node].data.clone();
        let mut leaves_whole = &tree.nodes[node].leaves.leaves_whole;
        let mut leaves_suffix = &tree.nodes[node].leaves.leaves_suffix;
        let empty = TinySet::default();
        let is_suffix_only_node =
            might_have_prefix_child_nodeids.is_empty() && leaves_whole.is_empty();
        while
            // three situations where we cut a note in its data field:
            // 1. the amount of data in the node exceeds 127, which is the limit
            data.len() > 0x3F ||
            // 2. the node's children are larger than the data limit, and it's a
            // suffix-only node, which means cutting off a suffix would likely
            // allow combining with another node
            // 3. a 1/128 that suffix nodes that are children of suffix nodes are also
            // going to be split (based on a hash, so that the same subtree gets split).
            (!data.is_empty() && is_suffix_only_node &&
                bundled_subtree_offsets[local_subtree_start..]
                .iter()
                .map(|(_, compressed)| compressed.len())
                .sum::<usize>()
                >= if parent_is_suffixes_only && bundled_subtree_hashes_lower.iter().fold(0, |a, b| a ^ *b) < 0xFFFF_0000 { FILE_SIZE_LIMIT } else { CHILD_IS_LARGE_LIMIT }
            )
        {
            let parent_data = data.start..if data.len() > 0x00_3F {
                data.end - 0x00_3F
            } else {
                data.end - 1
            };
            let c = tree.data[parent_data.end];
            let child_data = parent_data.end + 1..data.end;
            data = parent_data;
            let (child_node_id, child_node_offset) = stacker::maybe_grow(32 * 1024, 1024 * 1024, || {
                generate_node::<H>(
                    &might_have_prefix_child_nodeids,
                    &might_have_prefix_child_keys,
                    &suffix_only_child_nodeids,
                    &suffix_only_child_keys,
                    &tree.data[child_data],
                    leaves_whole,
                    leaves_suffix,
                    outbuf,
                )
            });
            if definitely_stack_compressible == DefinitelyStackCompressible::Yes {
                let child_compressed_offset = if might_have_prefix_child_nodeids.is_empty() && suffix_only_child_nodeids.is_empty() {
                    child_node_offset.clone()
                } else {
                    generate_definitely_stack_compressed_node(
                        child_node_offset.clone(),
                        outbuf,
                    )
                };
                bundled_subtree_hashes_lower.push(child_node_id as u32);
                bundled_subtree_hashes_upper.push((child_node_id >> 32) as u8);
                bundled_subtree_offsets.push((child_node_offset, child_compressed_offset));
            } else {
                bundled_subtree_hashes_lower.push(child_node_id as u32);
                bundled_subtree_hashes_upper.push((child_node_id >> 32) as u8);
                bundled_subtree_offsets.push((child_node_offset.clone(), child_node_offset));
                compress_node_branches(
                    &mut bundled_subtree_hashes_lower[local_subtree_start..],
                    &mut bundled_subtree_hashes_upper[local_subtree_start..],
                    &mut bundled_subtree_offsets[local_subtree_start..],
                    outbuf,
                );
            }
            might_have_prefix_child_nodeids.clear();
            might_have_prefix_child_keys.clear();
            suffix_only_child_nodeids.clear();
            suffix_only_child_keys.clear();
            if is_suffix_only_node {
                suffix_only_child_nodeids.push(child_node_id);
                suffix_only_child_keys.push(c);
            } else {
                might_have_prefix_child_nodeids.push(child_node_id);
                might_have_prefix_child_keys.push(c);
            }
            leaves_whole = &empty;
            leaves_suffix = &empty;
            if is_suffix_only_node {
                filename.clear();
                write_hash_to_filename(child_node_id, &mut filename);
                let outbuf_mark = outbuf.len();
                let flattened_child_data = subtree_to_bytes(
                    outbuf,
                    bundled_subtree_hashes_lower[local_subtree_start..]
                        .iter()
                        .copied()
                        .zip(bundled_subtree_hashes_upper[local_subtree_start..].iter().copied())
                        .zip(
                            bundled_subtree_offsets[local_subtree_start..]
                                .iter()
                                .cloned(),
                        ),
                );
                if file_existence_cache.contains(&child_node_id)
                    && let Some(other_content) = fs.read_file(&filename)?
                {
                    if other_content == flattened_child_data {
                        bundled_subtree_hashes_lower.truncate(local_subtree_start);
                        bundled_subtree_hashes_upper.truncate(local_subtree_start);
                        bundled_subtree_offsets.truncate(local_subtree_start);
                    }
                    outbuf.truncate(outbuf_mark);
                } else {
                    fs.write_file(&filename, flattened_child_data)?;
                    file_existence_cache.insert(child_node_id);
                    bundled_subtree_hashes_lower.truncate(local_subtree_start);
                    bundled_subtree_hashes_upper.truncate(local_subtree_start);
                    bundled_subtree_offsets.truncate(local_subtree_start);
                    outbuf.truncate(outbuf_mark);
                }
            }
            definitely_stack_compressible = DefinitelyStackCompressible::No;
        }
        let (node_id, node_offset) = generate_node::<H>(
            &might_have_prefix_child_nodeids,
            &might_have_prefix_child_keys,
            &suffix_only_child_nodeids,
            &suffix_only_child_keys,
            &tree.data[data],
            leaves_whole,
            leaves_suffix,
            outbuf,
        );
        if definitely_stack_compressible == DefinitelyStackCompressible::Yes {
            let compressed_offset = if might_have_prefix_child_nodeids.is_empty() && suffix_only_child_nodeids.is_empty() {
                node_offset.clone()
            } else {
                generate_definitely_stack_compressed_node(
                    node_offset.clone(),
                    outbuf,
                )
            };
            bundled_subtree_hashes_lower.push(node_id as u32);
            bundled_subtree_hashes_upper.push((node_id >> 32) as u8);
            bundled_subtree_offsets.push((node_offset, compressed_offset));
        } else {
            bundled_subtree_hashes_lower.push(node_id as u32);
            bundled_subtree_hashes_upper.push((node_id >> 32) as u8);
            bundled_subtree_offsets.push((node_offset.clone(), node_offset));
            compress_node_branches(
                &mut bundled_subtree_hashes_lower[local_subtree_start..],
                &mut bundled_subtree_hashes_upper[local_subtree_start..],
                &mut bundled_subtree_offsets[local_subtree_start..],
                outbuf,
            );
        }
        Ok(definitely_stack_compressible)
    }

    // Convert a canonical node's branches to its compressed form.
    //
    // There are two (and a half) compressed node types:
    // - stack compressed, where the pointers are implicitly set to the most
    //   recently decoded, unused nodes in the same file
    // - backref compressed, where the pointers are one byte backreferences
    //
    // The header (which is always 0/1 on a canonical node) represents that flag
    // in the second MSB. The first significant bit is for dictionary-compressed
    // data, which is done later.
    //
    // The remaining six bits are used to identify which branches are compressed,
    // because we allow mixing and matching. If all those bits are one, that's a
    // special case for compressing everything, even if there are more than six
    // branches.
    fn compress_node_branches(
        bundled_subtree_hashes_lower: &mut [u32],
        bundled_subtree_hashes_upper: &mut [u8],
        bundled_subtree_offsets: &mut [(Range<usize>, Range<usize>)],
        outbuf: &mut Vec<u8>,
    ) {
        // First, find backrefs for each child.
        let (canonical, existing_compressed) = bundled_subtree_offsets.last().unwrap().clone();
        let (
            NodeHeader {
                is_pure_suffixes_only_node,
                node_branch_repr,
                node_data_repr,
                is_no_leaves,
                is_no_branches,
                mhp_edges,
                so_edges,
                ..
            },
            mut canonical_i,
        ) = NodeHeader::parse(&outbuf[canonical.clone()]);
        let NodeDataRepr::Data {
            start: data_start,
            len: data_len,
        } = node_data_repr
        else {
            unreachable!("dictionary compression should happen later");
        };
        canonical_i += canonical.start;
        if node_branch_repr.is_inline_neighbors() || is_no_branches {
            // all branches are inline, nothing to compress
            return;
        }
        if mhp_edges.len() + so_edges.len() == 0 {
            return;
        }
        let mut calc_backref = || {
            let (&nodeid, _) = outbuf[canonical_i..].split_first_chunk().unwrap();
            let nodeid = decode::u40_from_be_bytes(nodeid);
            let nodeid_lower = nodeid as u32;
            let nodeid_upper = (nodeid >> 32) as u8;
            canonical_i += 5;
            if nodeid & 0x0000_0080_0000_0000u64 != 0 {
                // inline nodes never appear in the tree
                return Err(nodeid);
            }
            for (offset, other_nodeid_lower) in bundled_subtree_hashes_lower
                .iter()
                .rev()
                .skip(1)
                .take(256)
                .enumerate()
            {
                if *other_nodeid_lower == nodeid_lower
                    && bundled_subtree_hashes_upper[bundled_subtree_hashes_upper.len() - offset - 2]
                        == nodeid_upper
                {
                    return Ok(offset);
                }
            }
            Err(nodeid)
        };
        let mhp_backrefs = iter::repeat_with(&mut calc_backref)
            .take(mhp_edges.len())
            .collect::<Vec<_>>();
        let so_backrefs = iter::repeat_with(calc_backref)
            .take(so_edges.len())
            .collect::<Vec<_>>();
        if mhp_backrefs.iter().all(Result::is_err) && so_backrefs.iter().all(Result::is_err) {
            // Didn't find any of them. Cannot compress node.
            bundled_subtree_offsets.last_mut().unwrap().1 = canonical;
            return;
        }
        // If we found them, then generate the compressed form.
        let children_len = mhp_edges.len() + so_edges.len();
        let compressed_children_len = mhp_backrefs.iter().filter(|b| b.is_ok()).count()
            + so_backrefs.iter().filter(|b| b.is_ok()).count();
        let all_children_are_compressed = children_len == compressed_children_len;
        let is_long_compressed = if !all_children_are_compressed && children_len > 4 {
            if children_len > 12 {
                // Limited number of bits in the tag.
                bundled_subtree_offsets.last_mut().unwrap().1 = canonical;
                return;
            } else {
                true
            }
        } else {
            false
        };
        // If this node is compressible at all, then figure out if it's stack compressible,
        // specifically.
        let is_stack_compressible = mhp_backrefs
            .iter()
            .chain(so_backrefs.iter())
            .filter_map(|backref| backref.ok())
            .is_sorted()
            && {
                // calculate the state of the stack at this point
                let start_at = bundled_subtree_offsets.len()
                    - 2
                    - mhp_backrefs
                        .iter()
                        .chain(so_backrefs.iter())
                        .filter_map(|backref| backref.ok())
                        .next_back()
                        .unwrap();
                assert_eq!(
                    bundled_subtree_hashes_lower.len(),
                    bundled_subtree_offsets.len()
                );
                assert_eq!(
                    bundled_subtree_hashes_upper.len(),
                    bundled_subtree_offsets.len()
                );
                let offsets = &bundled_subtree_offsets[start_at..bundled_subtree_offsets.len() - 1];
                let mut stack: Vec<(usize, bool)> = Vec::with_capacity(offsets.len());
                for (other_node_backref, (_other_canonical, other_compressed)) in
                    offsets.iter().enumerate()
                {
                    let other_node_backref =
                        (bundled_subtree_offsets.len() - 2) - (other_node_backref + start_at);
                    let mut other_node_i = other_compressed.start;
                    let (other_node_header, other_node_i_consumed) =
                        NodeHeader::parse(&outbuf[other_node_i..]);
                    other_node_i += other_node_i_consumed;
                    match other_node_header.node_branch_repr {
                        NodeBranchRepr::Compressed {
                            is_stack_compressed: true,
                            is_long_compressed: _,
                            is_all_compressed,
                            compression_bitmap,
                        } => {
                            let mut stack_slot = stack.len();
                            'hit_end: for branchnum in 0..other_node_header.mhp_edges.len()
                                + other_node_header.so_edges.len()
                            {
                                if stack_slot == 0 {
                                    // we don't care about anything beyond the visible sliding window
                                    // at the decode end; the only reason we even execute stack ops here
                                    // is to set the "used" flag
                                    break 'hit_end;
                                }
                                if is_all_compressed || (compression_bitmap & (1 << branchnum)) != 0
                                {
                                    stack_slot -= 1;
                                    // skip consumed stack slots
                                    while stack[stack_slot].1 {
                                        if stack_slot == 0 {
                                            break 'hit_end;
                                        }
                                        stack_slot -= 1;
                                    }
                                    stack[stack_slot].1 = true;
                                }
                            }
                        }
                        NodeBranchRepr::Compressed {
                            is_stack_compressed: false,
                            is_long_compressed: _,
                            is_all_compressed,
                            compression_bitmap,
                        } => {
                            for branchnum in 0..other_node_header.mhp_edges.len()
                                + other_node_header.so_edges.len()
                            {
                                if is_all_compressed || (compression_bitmap & (1 << branchnum)) != 0
                                {
                                    let backref = outbuf[other_node_i] as usize;
                                    if !stack.is_empty() && (stack.len() - 1) >= backref {
                                        let backref_slot = stack.len() - 1 - backref;
                                        stack[backref_slot].1 = true;
                                    }
                                    other_node_i += 1;
                                } else {
                                    other_node_i += 5;
                                }
                            }
                        }
                        NodeBranchRepr::Canonical | NodeBranchRepr::InlineNeighbors { .. } => {}
                    }
                    // to manage the stack, we need to execute the same operations that the decoder will
                    // by keeping track of whether a particular node is consumed or not
                    stack.push((other_node_backref, false));
                }
                // check the offsets again
                let mut is_stack_compressible = true;
                for backref in mhp_backrefs.iter().chain(so_backrefs.iter()).flatten() {
                    if is_stack_compressible {
                        while stack.pop_if(|(_, consumed)| *consumed).is_some() {}
                        is_stack_compressible =
                            stack.last().map(|(backref, _)| backref) == Some(backref);
                        stack.pop();
                    }
                }
                is_stack_compressible
            };
        let new_data_start = outbuf.len();
        outbuf.push(
            if all_children_are_compressed {
                0xF0
            } else {
                0x00
            } | if is_long_compressed { 0x04 } else { 0x00 }
                | if is_stack_compressible { 0x02 } else { 0x00 }
                | if is_pure_suffixes_only_node {
                    0x01
                } else {
                    0x00
                }
                | if is_pure_suffixes_only_node && data_len == 0 && is_no_leaves {
                    0x08
                } else {
                    0x00
                },
        );
        if is_long_compressed {
            outbuf.push(0);
        }
        if !is_pure_suffixes_only_node || data_len != 0 || !is_no_leaves {
            let no_leaves_flag = if is_no_leaves { 0x80 } else { 0 };
            outbuf.push(data_len | no_leaves_flag);
            if !is_pure_suffixes_only_node {
                outbuf.extend_from_within(
                    canonical.start + data_start
                        ..canonical.start + data_start + usize::from(data_len),
                );
            }
        }
        assert!(children_len <= 256);
        if !is_pure_suffixes_only_node {
            mhp_edges.write(outbuf);
        }
        so_edges.write(outbuf);
        let mut tag_idx = 0;
        let mut tag_flag: i32 = 0;
        let mut write_backref = |backref| {
            match backref {
                Ok(backref) => {
                    if !is_stack_compressible {
                        let backref =
                            u8::try_from(backref).expect("search loop limited to 256 steps");
                        outbuf.push(backref);
                    }
                    if !all_children_are_compressed {
                        tag_flag |= 1 << tag_idx;
                    }
                }
                Err(nodeid) => {
                    outbuf.extend(u40_to_be_bytes(nodeid));
                }
            }
            tag_idx += 1;
        };
        mhp_backrefs.into_iter().for_each(&mut write_backref);
        so_backrefs.into_iter().for_each(write_backref);
        outbuf[new_data_start] |= u8::try_from(tag_flag & 0x0F).unwrap() << 4;
        if is_long_compressed {
            outbuf[new_data_start + 1] |= u8::try_from((tag_flag >> 4) & 0xFF).unwrap();
        }
        // copy child keys and leaves
        outbuf.extend_from_within(canonical_i..canonical.end);
        if outbuf[new_data_start..] == outbuf[existing_compressed.clone()] {
            outbuf.truncate(new_data_start);
        } else {
            bundled_subtree_offsets.last_mut().unwrap().1 = new_data_start..outbuf.len();
        }
    }
    /// Generate the code for a single node. The child IDs must be computed in order to call this file.
    fn generate_node<H: Hasher>(
        might_have_prefix_child_nodeids: &[u64],
        might_have_prefix_child_keys: &[u8],
        suffix_only_child_nodeids: &[u64],
        suffix_only_child_keys: &[u8],
        data: &[u8],
        whole: &[u32],
        suffix: &[u32],
        outbuf: &mut Vec<u8>,
    ) -> (u64, Range<usize>) {
        let mhp_len = might_have_prefix_child_keys.len();
        let so_len = suffix_only_child_keys.len();
        let pure_suffixes_only_node = so_len < 0x80 && mhp_len == 0 && whole.is_empty();
        let new_data_start = outbuf.len();
        let (no_leaves_flag, no_branches_flag) = if whole.is_empty()
            && suffix.is_empty()
            && pure_suffixes_only_node
            && data.is_empty()
        {
            outbuf.push(0x09); // empty data = 0x08 | pure_suffixes_only_node = 0x01
            (0x80, 0x00)
        } else {
            let no_leaves_flag = if whole.is_empty() && suffix.is_empty() {
                0x80
            } else {
                0x00
            };
            let no_branches_flag = if no_leaves_flag == 0 && mhp_len == 0 && so_len == 0 {
                0x40
            } else {
                0x00
            };
            outbuf.push(if pure_suffixes_only_node { 1 } else { 0 });
            assert!(data.len() <= 0x3F, "data too long");
            outbuf.push(
                u8::try_from(data.len()).expect("data len must be less than 64")
                    | no_leaves_flag
                    | no_branches_flag,
            );
            if !pure_suffixes_only_node {
                outbuf.extend(data);
            }
            (no_leaves_flag, no_branches_flag)
        };
        assert!(mhp_len + so_len <= 256);
        let mhp_edges = if pure_suffixes_only_node || no_branches_flag != 0 {
            NodeEdgeRepr::List(0)
        } else {
            let mhp_edges = NodeEdgeRepr::new(might_have_prefix_child_keys.iter().copied());
            mhp_edges.write(outbuf);
            mhp_edges
        };
        let so_edges = if no_branches_flag != 0 {
            NodeEdgeRepr::List(0)
        } else {
            let so_edges = NodeEdgeRepr::new(suffix_only_child_keys.iter().copied());
            so_edges.write(outbuf);
            so_edges
        };
        outbuf.extend(
            might_have_prefix_child_nodeids
                .iter()
                .chain(suffix_only_child_nodeids)
                .copied()
                .flat_map(u40_to_be_bytes),
        );
        if let NodeEdgeRepr::List(_) = mhp_edges {
            outbuf.extend_from_slice(might_have_prefix_child_keys);
        }
        if let NodeEdgeRepr::List(_) = so_edges {
            outbuf.extend_from_slice(suffix_only_child_keys);
        }
        if no_leaves_flag != 0 {
            // bitflag written above
        } else {
            // three possible special-case renderings
            // - 0x3a / 0x3b ... = magic number for roaring bitmap
            // - 0xnn where nn < 3a = tiny set stored inline
            // - 0xfn ... = tiny set with 16 bit offsets instead of 32 bit numbers
            // - oxen ... = tiny set where every number is in a single range
            fn serialize_special(domain: &[u32], outbuf: &mut Vec<u8>) {
                let stlen = outbuf.len();
                if (2..=0xff).contains(&domain.len())
                    // Check that the upper 16 bits of every item are the same,
                    // and that the nodes form a run. This way, on the decode side,
                    // we can directly construct a RoaringBitmapRun container,
                    // which requires both of these to be true.
                    && let runcountm1 = domain.windows(2).filter(|win| win[1] - win[0] != 1 || win[1] >> 16 != win[0] >> 16).count()
                    && runcountm1 <= 0x0f
                {
                    if domain.len() <= 0x3f && runcountm1 == 0 {
                        // represent a node with a single, long run
                        outbuf.reserve(5);
                        outbuf.push(0x80 | (domain.len() as u8));
                        outbuf.extend_from_slice(&u32::to_le_bytes(domain[0]));
                        return;
                    } else if (runcountm1 + 1) * 5 < domain.len() * 4 {
                        // represent a node with multiple, shorter runs
                        // in this mode, we pack two runs' length into a
                        // single byte, so each run must have <= 0x0f length
                        //
                        // since the layout can represent 16 runs, and each run
                        // is limited to 16 elements, the maximum domain len is
                        // 16x16, but we can't guarantee that each run is 16
                        // at this point, so bail out if it doesn't fit
                        let mut failed = false;
                        outbuf.push(0xe0 | (runcountm1 as u8));
                        let mut run_lengths = [0u8; 8];
                        let mut current_run = 0;
                        outbuf.extend_from_slice(&u32::to_le_bytes(domain[0]));
                        for win in domain.windows(2) {
                            if win[1] - win[0] == 1 && win[1] >> 16 == win[0] >> 16 {
                                run_lengths[current_run >> 1] =
                                    run_lengths[current_run >> 1].wrapping_add(1);
                                if run_lengths[current_run >> 1] & 0x0f == 0 {
                                    // too many in this run
                                    failed = true;
                                    break;
                                }
                            } else {
                                outbuf.extend_from_slice(&u32::to_le_bytes(win[1]));
                                if current_run % 2 == 0 {
                                    run_lengths[current_run >> 1] =
                                        run_lengths[current_run >> 1] << 4;
                                }
                                current_run += 1;
                            }
                        }
                        if current_run % 2 == 0 {
                            run_lengths[current_run >> 1] = run_lengths[current_run >> 1] << 4;
                        }
                        if failed {
                            outbuf.truncate(stlen);
                        } else {
                            let runcount = runcountm1 + 1;
                            outbuf.extend_from_slice(
                                &run_lengths[0..(runcount >> 1) + (runcount & 0x01)],
                            );
                            return;
                        }
                    }
                }
                encode::write_bitmap_to_bytes(domain, &mut *outbuf).unwrap();
                if outbuf.len() - stlen > domain.len() * 2 + 3 && (2..=0x0f).contains(&domain.len())
                {
                    if domain.windows(2).all(|win| win[1] - win[0] <= 0xff) {
                        outbuf.truncate(stlen);
                        outbuf.reserve(1 + size_of_val(domain));
                        outbuf.push(0xd0 | (domain.len() as u8));
                        outbuf.extend_from_slice(&u32::to_le_bytes(domain[0]));
                        outbuf.extend(domain.windows(2).map(|win| (win[1] - win[0]) as u8));
                        return;
                    } else if domain.windows(2).all(|win| win[1] - win[0] <= 0xffff) {
                        outbuf.truncate(stlen);
                        outbuf.reserve(1 + size_of_val(domain));
                        outbuf.push(0xf0 | (domain.len() as u8));
                        outbuf.extend_from_slice(&u32::to_le_bytes(domain[0]));
                        outbuf.extend(
                            domain
                                .windows(2)
                                .flat_map(|win| ((win[1] - win[0]) as u16).to_le_bytes()),
                        );
                        return;
                    }
                }
                if outbuf.len() - stlen > domain.len() * 4 + 1 && domain.len() < 0x3a {
                    outbuf.truncate(stlen);
                    outbuf.reserve(1 + size_of_val(domain));
                    outbuf.push(domain.len() as u8);
                    outbuf.extend(domain.iter().copied().flat_map(u32::to_le_bytes));
                }
            }
            if !pure_suffixes_only_node {
                serialize_special(whole, outbuf);
            }
            serialize_special(suffix, outbuf);
        }
        let nodeid = H::hash(&outbuf[new_data_start..outbuf.len()]) & 0x0000_007F_FFFF_FFFF;
        (nodeid, new_data_start..outbuf.len())
    }
    fn generate_definitely_stack_compressed_node(
        canonical: Range<usize>,
        outbuf: &mut Vec<u8>,
    ) -> Range<usize> {
        let (
            NodeHeader {
                is_pure_suffixes_only_node,
                node_branch_repr,
                node_data_repr,
                is_no_leaves,
                is_no_branches,
                mhp_edges,
                so_edges,
                ..
            },
            mut canonical_i,
        ) = NodeHeader::parse(&outbuf[canonical.clone()]);
        let NodeDataRepr::Data {
            start: data_start,
            len: data_len,
        } = node_data_repr
        else {
            unreachable!("dictionary compression should happen later");
        };
        canonical_i += canonical.start;
        assert!(!node_branch_repr.is_inline_neighbors());
        assert!(mhp_edges.len() + so_edges.len() > 0);
        assert!(!is_no_branches);
        // If we found them, then generate the compressed form.
        let children_len = mhp_edges.len() + so_edges.len();
        let mut compression_tag = 0u16;
        let (all_compressed, any_compressed) = if children_len > 12 {
            canonical_i += 5 * children_len;
            (true, true)
        } else {
            let mut all_compressed = true;
            let mut any_compressed = false;
            for child_idx in 0..children_len {
                if outbuf[canonical_i] & 0x80 == 0 {
                    compression_tag |= 1 << child_idx;
                    any_compressed = true;
                } else {
                    all_compressed = false;
                }
                canonical_i += 5;
            }
            (all_compressed, any_compressed)
        };
        if !any_compressed {
            return canonical;
        }
        let new_data_start = outbuf.len();
        outbuf.push(
            0x02 | if all_compressed {
                0xF0
            } else {
                u8::try_from((compression_tag << 4) & 0xF0).unwrap()
            } | if !all_compressed && compression_tag >= 0x0F {
                0x04
            } else {
                0x00
            } | if is_pure_suffixes_only_node {
                0x01
            } else {
                0x00
            } | if is_pure_suffixes_only_node && data_len == 0 && is_no_leaves {
                0x08
            } else {
                0x00
            },
        );
        if !all_compressed && compression_tag >= 0x0F {
            outbuf.push(u8::try_from(compression_tag >> 4).unwrap());
        }
        if !is_pure_suffixes_only_node || data_len != 0 || !is_no_leaves {
            let no_leaves_flag = if is_no_leaves { 0x80 } else { 0 };
            outbuf.push(data_len | no_leaves_flag);
            if !is_pure_suffixes_only_node {
                outbuf.extend_from_within(
                    canonical.start + data_start
                        ..canonical.start + data_start + usize::from(data_len),
                );
            }
        }
        assert!(children_len <= 256);
        if !is_pure_suffixes_only_node {
            mhp_edges.write(outbuf);
        }
        so_edges.write(outbuf);
        // copy any inlined nodes into place
        if !all_compressed {
            canonical_i -= children_len * 5;
            for _ in 0..children_len {
                if outbuf[canonical_i] & 0x80 != 0 {
                    outbuf.extend_from_within(canonical_i..canonical_i + 5);
                }
                canonical_i += 5;
            }
        }
        // copy child keys and leaves
        outbuf.extend_from_within(canonical_i..canonical.end);
        new_data_start..outbuf.len()
    }
    let mut bundled_subtree_hashes_lower: Vec<_> = Vec::with_capacity(tree.nodes.len() * 2 / 3);
    let mut bundled_subtree_hashes_upper: Vec<_> = Vec::with_capacity(tree.nodes.len() * 2 / 3);
    let mut bundled_subtree_offsets: Vec<(_, _)> = Vec::with_capacity(tree.nodes.len() * 2 / 3);
    let mut outbuf = Vec::new();
    let mut file_existence_cache = HashSet::new();
    generate_node_with_bundled_children::<H>(
        tree,
        0,
        0,
        false,
        fs,
        &mut file_existence_cache,
        &mut bundled_subtree_hashes_lower,
        &mut bundled_subtree_hashes_upper,
        &mut bundled_subtree_offsets,
        &mut outbuf,
    )?;
    Ok(subtree_to_bytes(
        &mut outbuf,
        iter::zip(bundled_subtree_hashes_lower, bundled_subtree_hashes_upper)
            .zip(bundled_subtree_offsets),
    )
    .to_vec())
}

/// Write a data column to disk.
///
/// A column is keyed by a contiguous ID number, and has a set of bytes as its value.
/// Empties are filtered out, and you can check if something's empty by
pub fn write_data_to_disk(
    data: impl Iterator<Item = impl AsRef<[u8]>>,
    dir_path: impl AsRef<Path>,
) -> Result<Vec<u8>, std::io::Error> {
    let dir_path = dir_path.as_ref();
    std::fs::create_dir_all(dir_path)?;

    struct Filesystem<'p> {
        dir_path: &'p Path,
    }

    impl fs::Filesystem for Filesystem<'_> {
        fn read_file(&mut self, _file_name: &str) -> std::io::Result<Option<Vec<u8>>> {
            unimplemented!()
        }

        fn write_file(&mut self, file_name: &str, contents: &[u8]) -> std::io::Result<()> {
            let full_path = self.dir_path.join(format!("{file_name}.js"));
            std::fs::write(full_path, contents)
        }
    }

    let mut fs = Filesystem { dir_path };

    write_data(data, &mut fs)
}

pub fn write_data<D: AsRef<[u8]>>(
    data: impl Iterator<Item = D>,
    fs: &mut impl Filesystem,
) -> Result<Vec<u8>, std::io::Error> {
    let mut empties: Vec<u32> = Vec::new();
    let mut partitions: Vec<(u64, u32)> = Vec::new();
    let mut current_partition: Vec<u8> = Vec::new();
    let mut current_partition_count = 0;
    let mut previous_data: VecDeque<D> = VecDeque::new();
    let mut filename = String::new();
    fn flush<D: AsRef<[u8]>>(
        current_partition: &mut Vec<u8>,
        current_partition_count: &mut u32,
        previous_data: &mut VecDeque<D>,
        partitions: &mut Vec<(u64, u32)>,
        filename: &mut String,
        fs: &mut impl Filesystem,
    ) -> Result<(), std::io::Error> {
        let hash = siphash_of_bytes(current_partition, 0, 0) & 0x0000_00FF_FFFF_FFFF;
        filename.clear();
        write_hash_to_filename(hash, filename);
        //use std::fmt::Write;
        //write!(filename, ".{}", partitions.len()).unwrap();
        let mut output = Vec::with_capacity(current_partition.len() + 6);
        output.extend_from_slice(br#"rd_(""#);
        output.extend(current_partition.escape_ascii());
        output.extend_from_slice(br#"")"#);
        if (output.len() - 7) > (current_partition.len() * 3) / 2 {
            output.clear();
            output.extend_from_slice(br#"rb_(""#);
            write_base64_to_bytes(current_partition, &mut output)?;
            output.extend_from_slice(br#"")"#);
        }
        fs.write_file(filename, &output)?;
        partitions.push((hash, *current_partition_count));
        *current_partition_count = 0;
        current_partition.clear();
        previous_data.clear();
        Ok(())
    }
    for (id, data_) in data.enumerate() {
        let data = data_.as_ref();
        if data.is_empty() {
            empties.push(id.try_into().unwrap());
        } else {
            if current_partition.len() + data.len() > FILE_SIZE_LIMIT {
                flush(
                    &mut current_partition,
                    &mut current_partition_count,
                    &mut previous_data,
                    &mut partitions,
                    &mut filename,
                    fs,
                )?;
            }
            if let Some(i) = previous_data.iter().position(|prev| prev.as_ref() == data) {
                current_partition.push(b'0' + (i as u8));
            } else {
                encode::write_vlqhex_to_bytes(
                    u32::try_from(data.len()).unwrap(),
                    &mut current_partition,
                );
                current_partition.extend_from_slice(data);
                previous_data.push_front(data_);
                if previous_data.len() > 16 {
                    previous_data.pop_back();
                }
            }
            current_partition_count += 1;
        }
    }
    flush(
        &mut current_partition,
        &mut current_partition_count,
        &mut previous_data,
        &mut partitions,
        &mut filename,
        fs,
    )?;
    let mut result = Vec::new();
    result.extend_from_slice(br#""N":""#);
    for &(_, n) in &partitions {
        encode::write_vlqhex_to_bytes(n, &mut result);
    }
    result.extend_from_slice(br#"","E":""#);
    let mut empties_bytes = Vec::new();
    encode::write_bitmap_to_bytes(&empties, &mut empties_bytes).unwrap();
    encode::write_base64_to_bytes(&empties_bytes, &mut result)?;
    result.extend_from_slice(br#"","H":""#);
    let _ = encode::write_base64_to_bytes(
        partitions
            .into_iter()
            .map(|(h, _)| h)
            .flat_map(u40_to_be_bytes)
            .collect::<Vec<u8>>()
            .as_slice(),
        &mut result,
    );
    result.push(b'"');
    Ok(result)
}

#[derive(Debug)]
pub enum ReadDataError<E> {
    Io(std::io::Error),
    InvalidRoot,
    InvalidPartition { hash: u64, pos: usize },
    ConsumerError(E),
}

impl<E> std::fmt::Display for ReadDataError<E>
where
    E: std::fmt::Display,
{
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ReadDataError::Io(io) => <std::io::Error as std::fmt::Display>::fmt(io, f),
            ReadDataError::InvalidRoot => write!(f, "invalid root file"),
            &ReadDataError::InvalidPartition { hash, pos } => {
                let mut filename = String::new();
                write_hash_to_filename(hash, &mut filename);
                write!(f, "invalid partition file: {filename} : {pos}")
            }
            ReadDataError::ConsumerError(e) => {
                write!(f, "data consumer error: {e}")
            }
        }
    }
}

pub fn scan_column_in_root<'root>(
    root: &'root [u8],
    column_name: &'root [u8],
) -> Option<&'root [u8]> {
    if column_name.is_empty()
        || column_name
            .iter()
            .any(|&c| !matches!(c, b'a'..=b'z' | b'A'..=b'Z' | b'0'..=b'9' | b'-' | b'_'))
    {
        return None;
    }
    let mut root = root
        .strip_prefix(br#"rr_('{"#)
        .and_then(|root| root.strip_suffix(br#"}')"#))?;
    loop {
        root = root.strip_prefix(br#"""#)?;
        if let Some(potentially_needle) = root.strip_prefix(column_name)
            && let Some(needle) = potentially_needle.strip_prefix(br#"":{"#)
        {
            return Some(&needle[..needle.iter().position(|&c| c == b'}')?]);
        }
        root = &root[root.iter().position(|&c| c == b'"')? + 1..];
        root = root.strip_prefix(br#":{"#)?;
        root = &root[root.iter().position(|&c| c == b'}')? + 1..];
        root = root.strip_prefix(br#","#)?;
    }
}

pub fn scan_column_parts(
    mut column_root: &[u8],
) -> Option<(Vec<u32>, crate::internals::decode::RoaringBitmap, Vec<u64>)> {
    let mut n = None;
    let mut e = None;
    let mut h = None;
    loop {
        let target = match column_root {
            [b'"', b'N', b'"', b':', remaining @ ..] => {
                column_root = remaining;
                &mut n
            }
            [b'"', b'E', b'"', b':', remaining @ ..] => {
                column_root = remaining;
                &mut e
            }
            [b'"', b'H', b'"', b':', remaining @ ..] => {
                column_root = remaining;
                &mut h
            }
            _ => {
                column_root = column_root.strip_prefix(br#"""#)?;
                column_root = &column_root[column_root.iter().position(|&c| c == b'"')? + 1..];
                column_root = column_root.strip_prefix(br#":""#)?;
                column_root = &column_root[column_root.iter().position(|&c| c == b'"')? + 1..];
                column_root = column_root.strip_prefix(br#","#)?;
                continue;
            }
        };
        column_root = column_root.strip_prefix(br#"""#)?;
        let end = column_root.iter().position(|&c| c == b'"')?;
        let (data, remaining) = column_root.split_at(end);
        *target = Some(data);
        if let (Some(mut n), Some(e), Some(h)) = (n, e, h) {
            let mut numbers = Vec::new();
            while !n.is_empty() {
                let (num, i) = decode::read_vlqhex_from_bytes(n)?;
                n = &n[i..];
                numbers.push(num);
            }
            let mut hash_bucket = Vec::new();
            read_base64_from_bytes(h, &mut hash_bucket).ok()?;
            let hashes = hash_bucket
                .as_chunks()
                .0
                .iter()
                .copied()
                .map(u40_from_be_bytes)
                .collect();
            let mut empties = Vec::new();
            read_base64_from_bytes(e, &mut empties).ok()?;
            let (empties, _) = decode::RoaringBitmap::from_bytes(&empties)?;
            return Some((numbers, empties, hashes));
        }
        column_root = remaining.strip_prefix(br#"","#)?;
    }
}

pub fn read_data_from_disk_column<E>(
    root_path: impl AsRef<Path>,
    column_name: &[u8],
    column_path: impl AsRef<Path>,
    consumer: &mut impl Consumer<Err = E>,
) -> Result<(), ReadDataError<E>> {
    let root = std::fs::read(root_path).map_err(ReadDataError::Io)?;
    let column_path = column_path.as_ref();

    fn loader(column_path: &Path) -> impl FnMut(&str, &mut Vec<u8>) -> io::Result<()> {
        |filename, buf| {
            let path = column_path.join(format!("{filename}.js"));
            std::fs::File::open(path)?.read_to_end(buf)?;
            Ok(())
        }
    }

    read_data_from_column(&root, column_name, &mut loader(column_path), consumer)
}

pub trait Loader {
    fn load(&mut self, filename: &str, buf: &mut Vec<u8>) -> io::Result<()>;
}

impl<F> Loader for F
where
    F: FnMut(&str, &mut Vec<u8>) -> io::Result<()>,
{
    fn load(&mut self, filename: &str, buf: &mut Vec<u8>) -> io::Result<()> {
        self(filename, buf)
    }
}

pub trait Consumer {
    type Err;

    fn consume(&mut self, id: u32, cell: &[u8]) -> Result<(), Self::Err>;
}

impl<F, Err> Consumer for F
where
    F: FnMut(u32, &[u8]) -> Result<(), Err>,
{
    type Err = Err;

    fn consume(&mut self, id: u32, cell: &[u8]) -> Result<(), Self::Err> {
        self(id, cell)
    }
}

pub fn read_data_from_column<'root, E>(
    root: &'root [u8],
    column_name: &'root [u8],
    loader: &mut impl Loader,
    consumer: &mut impl Consumer<Err = E>,
) -> Result<(), ReadDataError<E>> {
    let column_root = scan_column_in_root(root, column_name).ok_or(ReadDataError::InvalidRoot)?;
    let (counts, empties, hashes) =
        scan_column_parts(column_root).ok_or(ReadDataError::InvalidRoot)?;
    let mut entry = 0;
    let mut bucket_raw = Vec::new();
    let mut bucket = Vec::new();
    let mut filename = String::new();
    for (&count, &hash) in counts.iter().zip(hashes.iter()) {
        filename.clear();
        write_hash_to_filename(hash, &mut filename);
        bucket_raw.clear();
        bucket.clear();
        loader
            .load(&filename, &mut bucket_raw)
            .map_err(ReadDataError::Io)?;
        let mut pos = 0;
        if let Some(inner) = bucket_raw.strip_prefix(br#"rd_(""#)
            && let Some(inner) = inner.strip_suffix(br#"")"#)
        {
            decode::unescape_ascii(inner, &mut bucket)
                .ok_or(ReadDataError::InvalidPartition { hash, pos })?;
        } else if let Some(inner) = bucket_raw.strip_prefix(br#"rb_(""#)
            && let Some(inner) = inner.strip_suffix(br#"")"#)
        {
            read_base64_from_bytes(inner, &mut bucket)
                .map_err(|_| ReadDataError::InvalidPartition { hash, pos })?;
        } else {
            return Err(ReadDataError::InvalidPartition { hash, pos: !0 });
        }
        let mut backrefs = VecDeque::new();
        for _ in 0..count {
            while empties.contains(entry) {
                consumer
                    .consume(entry, b"")
                    .map_err(ReadDataError::ConsumerError)?;
                entry += 1;
            }
            let c = bucket[pos];
            if c >= 48 && c <= 63 {
                // 48 = "0", 63 = "?"
                consumer
                    .consume(entry, backrefs[usize::from(c - 48)])
                    .map_err(ReadDataError::ConsumerError)?;
                pos += 1;
            } else {
                let (len, consumed) = decode::read_vlqhex_from_bytes(&bucket[pos..])
                    .ok_or(ReadDataError::InvalidPartition { hash, pos })?;
                let len = usize::try_from(len).unwrap();
                pos += consumed;
                consumer
                    .consume(entry, &bucket[pos..pos + len])
                    .map_err(ReadDataError::ConsumerError)?;
                backrefs.push_front(&bucket[pos..pos + len]);
                if backrefs.len() > 16 {
                    backrefs.pop_back();
                }
                pos += len;
            }
            entry += 1;
        }
    }
    while empties.contains(entry) {
        consumer
            .consume(entry, b"")
            .map_err(ReadDataError::ConsumerError)?;
        entry += 1;
    }
    Ok(())
}

